  --marigold-hot: #f7b954;
  --coral: #f2958f;
  --coral-soft: #f6b1a9;
  --marble: #f4efe6;
  --marble-dim: #cfd8d9;
  --gold: #d8a531;
  --serif: "Fraunces", "Iowan Old Style", Georgia, serif;
  --mono: "IBM Plex Mono", ui-monospace, "SF Mono", monospace;
  --ease-lux: cubic-bezier(0.22, 1, 0.36, 1);
}

