  font-family: var(--serif);
  font-weight: 300;
  line-height: 1.55;
  overflow-x: clip;
  -webkit-font-smoothing: antialiased;
}

::selection { background: var(--marigold); color: var(--ink-deep); }

.mono {
  font-family: var(--mono);
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-weight: 400;
}

em { font-style: italic; font-weight: 400; }

img { max-width: 100%; display: block; }

/* ─────────────── grain ─────────────── */
.grain {
  position: fixed; inset: -50%; width: 200%; height: 200%;
  pointer-events: none; z-index: 300; opacity: 0.05;
  mix-blend-mode: overlay;
}

/* ─────────────── gate (loader) ─────────────── */
.gate { position: fixed; inset: 0; z-index: 200; pointer-events: none; }
.gate__door {
  position: absolute; top: 0; bottom: 0; width: 50.5%;
  background: var(--ink-deep);
  transition: transform 1.1s var(--ease-lux) 0.9s;
}
.gate__door--l { left: 0; border-right: 1px solid rgba(216,165,49,0.35); }
.gate__door--r { right: 0; border-left: 1px solid rgba(216,165,49,0.35); }
.gate__seal {
  position: absolute; inset: 0; display: flex; flex-direction: column;
  align-items: center; justify-content: center; gap: 1rem;
  transition: opacity 0.5s ease 0.55s;
}
.gate__word {
  font-family: var(--serif); font-weight: 900;
  font-size: clamp(1.6rem, 4vw, 3rem);
  color: var(--marigold);
  animation: gatePulse 1.4s var(--ease-lux) both;
}
.gate__sub {
  font-family: var(--mono); font-size: 0.65rem; letter-spacing: 0.3em;
  text-transform: uppercase; color: var(--marble-dim); opacity: 0.7;
}
@keyframes gatePulse {
  from { letter-spacing: 0.6em; opacity: 0; }
  to   { letter-spacing: 0.12em; opacity: 1; }
}
.gate.gate--open .gate__door--l { transform: translateX(-101%); }
.gate.gate--open .gate__door--r { transform: translateX(101%); }
.gate.gate--open .gate__seal { opacity: 0; }

/* ─────────────── cursor ─────────────── */
.cursor {
  position: fixed; top: 0; left: 0; z-index: 250;
  width: 14px; height: 14px; border-radius: 50%;
  border: 1px solid var(--marigold);
  pointer-events: none; opacity: 0;
  transform: translate(-50%, -50%);
  transition: width 0.35s var(--ease-lux), height 0.35s var(--ease-lux),
              background 0.35s, opacity 0.3s;
  display: flex; align-items: center; justify-content: center;
}
.cursor--on { opacity: 1; }
.cursor--hover { width: 58px; height: 58px; background: rgba(242,160,61,0.12); backdrop-filter: blur(2px); }
.cursor__label {
  font-family: var(--mono); font-size: 0.5rem; letter-spacing: 0.18em;
  text-transform: uppercase; color: var(--marigold);
  opacity: 0; transition: opacity 0.25s;
  white-space: nowrap;
}
.cursor--hover .cursor__label { opacity: 1; }
@media (hover: none), (pointer: coarse) { .cursor { display: none; } }

/* ─────────────── nav ─────────────── */
.nav {
  position: fixed; top: 0; left: 0; right: 0; z-index: 100;
  display: flex; align-items: center; justify-content: space-between;
  padding: 1.1rem clamp(1.2rem, 4vw, 3rem);
  mix-blend-mode: normal;
  transition: transform 0.5s var(--ease-lux);
}
.nav--hidden { transform: translateY(-110%); }
.nav__mark {
  font-family: var(--serif); font-weight: 900; letter-spacing: 0.14em;
  font-size: 0.95rem; color: var(--marble); text-decoration: none;
}
.nav__mark sup { color: var(--marigold); font-weight: 400; }
.nav__where {
  font-family: var(--mono); font-size: 0.6rem; letter-spacing: 0.24em;
  text-transform: uppercase; color: var(--marble-dim);
  position: absolute; left: 50%; transform: translateX(-50%);
}
.nav__dots { display: flex; gap: 0.9rem; align-items: center; }
.nav__dots a { position: relative; padding: 6px; display: grid; place-items: center; }
.nav__dots i {
  width: 7px; height: 7px; border-radius: 50%;
  border: 1px solid var(--marble-dim); display: block;
  transition: background 0.3s, border-color 0.3s, transform 0.3s;
}
.nav__dots a:hover i, .nav__dots a.on i {
  background: var(--marigold); border-color: var(--marigold); transform: scale(1.25);
}
.nav__dots a::after {
  content: attr(data-hint);
  position: absolute; top: calc(100% + 4px); right: 0;
  font-family: var(--mono); font-size: 0.55rem; letter-spacing: 0.16em;
  text-transform: uppercase; color: var(--marigold); white-space: nowrap;
  opacity: 0; transform: translateY(-4px); transition: 0.25s;
  pointer-events: none;
}
.nav__dots a:hover::after { opacity: 1; transform: translateY(0); }
@media (max-width: 720px) { .nav__where { display: none; } }

/* ─────────────── hero ─────────────── */
.hero {
  position: relative; min-height: 100svh;
  display: flex; flex-direction: column; justify-content: center;
  padding: clamp(5rem, 12vh, 8rem) clamp(1.2rem, 4vw, 3rem) 3rem;
  overflow: clip;
  background:
    radial-gradient(120% 90% at 80% -10%, rgba(242,149,143,0.22), transparent 55%),
    radial-gradient(100% 80% at 10% 110%, rgba(242,160,61,0.12), transparent 50%),
    var(--ink);
}
.hero__sky {
  position: absolute; inset: -12% -5%;
  background-image: url("public/img/still-life.png");
  background-size: cover; background-position: 50% 12%;
  opacity: 0.14; filter: saturate(0.7) blur(1px);
  pointer-events: none;
}
.hero__over { color: var(--coral); position: relative; margin-bottom: 1rem; }
.hero__title {
  position: relative; line-height: 0.82; margin-left: -0.06em;
  user-select: none;
}
.hero__letters {
  font-weight: 900;
  font-size: clamp(4.2rem, 17.5vw, 16.5rem);
  letter-spacing: -0.015em;
  background-image: url("public/img/still-life.png");
  background-size: 130%; background-position: 50% 40%;
  -webkit-background-clip: text; background-clip: text;
  color: transparent;
  -webkit-text-stroke: 1px rgba(244,239,230,0.28);
  display: inline-block;
  filter: saturate(1.25) contrast(1.05);
}
.hero__cols {
  position: relative; display: flex; justify-content: space-between;
  align-items: flex-end; gap: 2rem; margin-top: clamp(1.5rem, 4vh, 3rem);
  max-width: 100%;
}
.hero__claim {
  max-width: 34rem; font-size: clamp(1.02rem, 1.6vw, 1.3rem);
  color: var(--marble);
}
.hero__claim em { color: var(--marigold-hot); }
.hero__hint { color: var(--marble-dim); flex-shrink: 0; }
.hero__arrow { display: inline-block; animation: bob 1.8s ease-in-out infinite; }
@keyframes bob { 0%,100% { transform: translateY(0); } 50% { transform: translateY(5px); } }
.hero__bust {
  position: absolute; right: clamp(-4rem, -2vw, 0rem); top: 6%;
  width: clamp(180px, 26vw, 420px); aspect-ratio: 3/4;
  background-image: url("public/img/still-life.png");
  background-size: 300%; background-position: 92% 30%;
  border-radius: 999px 999px 0 0;
  border: 1px solid rgba(216,165,49,0.5);
  box-shadow: 0 30px 80px rgba(0,0,0,0.45);
  opacity: 0.92;
}
@media (max-width: 900px) {
  .hero__bust { width: 34vw; top: 10%; opacity: 0.5; }
  .hero__cols { flex-direction: column; align-items: flex-start; }
}

/* ─────────────── marquee ─────────────── */
.marquee {
  overflow: hidden; white-space: nowrap;
  border-top: 1px solid rgba(216,165,49,0.4);
  border-bottom: 1px solid rgba(216,165,49,0.4);
  background: var(--marigold); color: var(--ink-deep);
  padding: 0.65rem 0; position: relative; z-index: 2;
}
.marquee__track { display: inline-flex; animation: slide 26s linear infinite; }
.marquee__track span {
  font-family: var(--mono); font-size: 0.72rem; letter-spacing: 0.22em;
  font-weight: 500;
}
@keyframes slide { to { transform: translateX(-50%); } }

/* ─────────────── chapters shared ─────────────── */
.chapter { padding: clamp(5rem, 12vh, 9rem) clamp(1.2rem, 4vw, 3rem); position: relative; }
.chapter__head { margin-bottom: clamp(2.5rem, 6vh, 4.5rem); max-width: 72rem; }
.chapter__num { color: var(--coral); display: block; margin-bottom: 0.8rem; }
.chapter__title {
  font-weight: 900; font-size: clamp(2.6rem, 7vw, 6rem);
  line-height: 0.95; letter-spacing: -0.01em;
}
.chapter__lede {
  margin-top: 1.2rem; font-size: clamp(1rem, 1.5vw, 1.25rem);
  max-width: 40rem; color: var(--marble-dim);
}
.chapter__aside { color: var(--marigold); letter-spacing: 0.2em; }

/* ─────────────── I · collection ─────────────── */
.collection {
  background:
    radial-gradient(90% 60% at 100% 0%, rgba(242,149,143,0.08), transparent 60%),
    var(--ink);
}
.artifacts { list-style: none; border-top: 1px solid rgba(244,239,230,0.18); }
.artifact { border-bottom: 1px solid rgba(244,239,230,0.18); }
.artifact__row {
  width: 100%; display: grid;
  grid-template-columns: 6rem 1fr 1.2fr;
  align-items: baseline; gap: 1.5rem;
  padding: 1.6rem 0.4rem;
  background: none; border: 0; color: inherit; text-align: left;
  font: inherit; cursor: pointer;
  transition: padding 0.4s var(--ease-lux), background 0.4s;
}
.artifact__idx { color: var(--marigold); }
.artifact__name {
  font-size: clamp(1.5rem, 3.4vw, 2.6rem); font-weight: 600;
  font-style: italic; line-height: 1.05;
  transition: color 0.3s, transform 0.45s var(--ease-lux);
}
.artifact__note { color: var(--marble-dim); font-size: clamp(0.9rem, 1.3vw, 1.05rem); }
@media (hover: hover) {
  .artifact__row:hover { padding-left: 1.2rem; background: rgba(242,160,61,0.05); }
  .artifact__row:hover .artifact__name { color: var(--marigold-hot); }
}
.artifact__inline { display: none; }

/* the floating lens (desktop) */
.lens {
  position: fixed; z-index: 90; width: 250px; height: 320px;
  pointer-events: none; opacity: 0;
  transition: opacity 0.3s;
  filter: drop-shadow(0 24px 50px rgba(0,0,0,0.55));
}
.lens--on { opacity: 1; }
.lens__img {
  width: 100%; height: 100%;
  border-radius: 999px 999px 8px 8px;
  border: 1px solid var(--gold);
  background-image: url("public/img/still-life.png");
  background-size: 300%; background-position: 50% 50%;
  transition: background-position 0.5s var(--ease-lux);
}
.lens__tag {
  position: absolute; bottom: -1.4rem; left: 50%; transform: translateX(-50%);
  color: var(--marigold); font-size: 0.58rem; white-space: nowrap;
}

/* mobile inline artifact figures */
@media (hover: none), (pointer: coarse) {
  .lens { display: none; }
  .artifact__inline {
    display: block; overflow: hidden; max-height: 0;
    transition: max-height 0.6s var(--ease-lux), margin 0.6s var(--ease-lux);
    margin: 0 0.4rem;
  }
  .artifact.open .artifact__inline { max-height: 360px; margin-bottom: 1.6rem; }
  .artifact__inline::before {
    content: ""; display: block; height: 250px;
    border-radius: 999px 999px 8px 8px;
    border: 1px solid var(--gold);
    background-image: url("public/img/still-life.png");
    background-size: var(--zoom, 300%); background-position: var(--pos, 50% 50%);
    max-width: 300px; margin: 0 auto;
  }
  .artifact__inline figcaption {
    text-align: center; color: var(--marigold); margin-top: 0.6rem; font-size: 0.58rem;
  }
}

/* full plate */
.collection__plate { margin-top: clamp(3rem, 8vh, 6rem); }
.collection__plateImg {
  height: clamp(300px, 62vh, 640px);
  background-image: url("public/img/still-life.png");
  background-size: cover; background-position: 50% 30%;
  border: 1px solid rgba(216,165,49,0.55);
  border-radius: 4px;
  box-shadow: 0 40px 100px rgba(0,0,0,0.5);
  will-change: background-position;
}
.collection__plate figcaption { margin-top: 0.9rem; color: var(--marble-dim); font-size: 0.62rem; }

/* ─────────────── II · scholars ─────────────── */
.scholars {
  background:
    linear-gradient(180deg, var(--ink) 0%, #123040 55%, var(--ink) 100%);
}
.scholars__grid {
  display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.1fr);
  gap: clamp(2rem, 6vw, 6rem); align-items: start;
  max-width: 78rem;
}
.scholars__arch { position: sticky; top: 12vh; }
.scholars__img {
  aspect-ratio: 4/5;
  border-radius: 999px 999px 0 0;
  border: 1px solid var(--gold);
  background-image: url("public/img/scholar.png");
  background-size: 190%; background-position: 32% 40%;
  box-shadow: 0 40px 90px rgba(0,0,0,0.5);
  will-change: background-position;
  transition: transform 0.6s var(--ease-lux);
}
.scholars__arch:hover .scholars__img { transform: scale(1.015) rotate(-0.4deg); }
.scholars__arch figcaption { margin-top: 0.9rem; color: var(--marble-dim); font-size: 0.6rem; text-align: center; }
.scholars__text { padding-top: clamp(0rem, 4vh, 3rem); }
.scholars__body {
  font-size: clamp(1.05rem, 1.6vw, 1.35rem); margin-bottom: 1.8rem;
  max-width: 34rem;
}
.scholars__body em { color: var(--coral-soft); }
.dropcap {
  float: left; font-weight: 900; font-size: 4.6em; line-height: 0.78;
  padding: 0.04em 0.12em 0 0; color: var(--marigold);
}
.scholars__quote {
  margin-top: clamp(2rem, 5vh, 3.5rem);
  border-left: 2px solid var(--marigold);
  padding-left: clamp(1.2rem, 3vw, 2rem);
}
.scholars__quote p {
  font-size: clamp(1.4rem, 2.6vw, 2.1rem); font-weight: 600; font-style: italic;
  line-height: 1.25; color: var(--marble);
}
.scholars__quote em { color: var(--marigold-hot); }
.scholars__quote cite { display: block; margin-top: 1rem; color: var(--marble-dim); font-style: normal; font-size: 0.6rem; }
@media (max-width: 860px) {
  .scholars__grid { grid-template-columns: 1fr; }
  .scholars__arch { position: relative; top: 0; max-width: 420px; margin: 0 auto; }
}

/* ─────────────── III · portal ─────────────── */
.portal { height: 320vh; position: relative; background: var(--ink-deep); }
.portal__sticky {
  position: sticky; top: 0; height: 100svh;
  display: grid; place-items: center; overflow: clip;
}
.portal__frame {
  position: relative;
  width: var(--pw, 34vmin); height: var(--ph, 52vmin);
  border-radius: var(--pr, 999px) var(--pr, 999px) 6px 6px;
  overflow: hidden;
  border: 1px solid var(--gold);
  box-shadow: 0 0 0 1px rgba(8,24,33,0.8), 0 60px 140px rgba(0,0,0,0.6);
  will-change: width, height, border-radius;
}
.portal__img {
  position: absolute; inset: -6%;
  background-image: url("public/img/valley.png");
  background-size: cover; background-position: 50% 55%;
  will-change: background-position;
}
.portal__caption {
  position: absolute; inset: 0; display: flex; flex-direction: column;
  justify-content: flex-end; padding: clamp(1.2rem, 4vw, 3.5rem);
  background: linear-gradient(180deg, transparent 40%, rgba(8,24,33,0.82) 100%);
  opacity: var(--pcap, 0); transition: opacity 0.2s linear;
}
.portal__title { font-weight: 900; font-size: clamp(2.4rem, 6.5vw, 5.5rem); line-height: 0.95; }
.portal__lede {
  margin-top: 0.9rem; max-width: 36rem;
  font-size: clamp(0.98rem, 1.5vw, 1.25rem); color: var(--marble);
}
.portal__hint {
  position: absolute; bottom: -2.4rem; left: 50%; transform: translateX(-50%);
  color: var(--marble-dim); white-space: nowrap; font-size: 0.58rem;
  opacity: calc(1 - var(--pcap, 0));
}

/* ─────────────── IV · temple ─────────────── */
.temple {
  position: relative; min-height: 130svh;
  display: flex; align-items: flex-end;
  overflow: clip;
  background: var(--ink-deep);
}
.temple__stars { position: absolute; inset: 0; width: 100%; height: 100%; z-index: 1; opacity: 0.9; }
.temple__img {
  position: absolute; inset: -8% 0;
  background-image: url("public/img/temple.png");
  background-size: cover; background-position: 50% 68%;
  z-index: 0;
}
.temple__veil {
  position: absolute; inset: 0; z-index: 2;
  background:
    linear-gradient(180deg, var(--ink-deep) 0%, rgba(8,24,33,0.25) 30%, transparent 55%, rgba(8,24,33,0.9) 100%);
}
.temple__content {
  position: relative; z-index: 3;
  padding: 40svh clamp(1.2rem, 4vw, 3rem) clamp(4rem, 10vh, 7rem);
  max-width: 46rem;
}
.temple__title {
  font-weight: 900; font-size: clamp(2.8rem, 7.5vw, 6.5rem);
  line-height: 0.95; text-shadow: 0 8px 40px rgba(8,24,33,0.8);
}
.temple__lede {
  margin: 1.4rem 0 2.2rem; font-size: clamp(1.02rem, 1.6vw, 1.3rem);
  color: var(--marble); text-shadow: 0 2px 18px rgba(8,24,33,0.9);
}
.temple__lede em { color: var(--marigold-hot); }
.temple__cta {
  position: relative; overflow: hidden;
  font-family: var(--mono); font-size: 0.72rem; letter-spacing: 0.24em;
  text-transform: uppercase; font-weight: 500;
  color: var(--ink-deep); background: var(--marigold);
  border: 1px solid var(--marigold);
  padding: 1.1rem 2.4rem; cursor: pointer;
  transition: background 0.4s var(--ease-lux), color 0.4s, transform 0.4s var(--ease-lux);
}
.temple__cta:hover { transform: translateY(-2px); background: var(--marigold-hot); }
.temple__cta:active { transform: translateY(0); }
.temple__ctaText, .temple__ctaAlt { display: block; transition: transform 0.5s var(--ease-lux), opacity 0.4s; }
.temple__ctaAlt { position: absolute; inset: 0; display: grid; place-items: center; transform: translateY(110%); }
.temple__cta.done { background: var(--ink-deep); color: var(--marigold); }
.temple__cta.done .temple__ctaText { transform: translateY(-110%); opacity: 0; }
.temple__cta.done .temple__ctaAlt { transform: translateY(0); }
.temple__fine { margin-top: 1.4rem; color: var(--marble-dim); font-size: 0.6rem; }

/* ─────────────── footer ─────────────── */
.foot {
  background: var(--ink-deep);
  border-top: 1px solid rgba(216,165,49,0.4);
  padding: 2.5rem clamp(1.2rem, 4vw, 3rem) 2rem;
}
.foot__row {
  display: flex; flex-wrap: wrap; gap: 1.5rem;
  align-items: baseline; justify-content: space-between;
}
.foot__mark { font-weight: 900; letter-spacing: 0.14em; font-size: 1.1rem; }
.foot__mark sup { color: var(--marigold); font-weight: 400; }
.foot__cols { display: flex; flex-wrap: wrap; gap: 1.5rem; color: var(--marble-dim); font-size: 0.6rem; }
.foot__legal { margin-top: 1.8rem; color: rgba(207,216,217,0.5); font-size: 0.58rem; text-transform: none; letter-spacing: 0.08em; }

/* ─────────────── reveals ─────────────── */
.reveal {
  opacity: 0; transform: translateY(28px);
  transition: opacity 0.9s var(--ease-lux), transform 0.9s var(--ease-lux);
}
.reveal.in { opacity: 1; transform: none; }

/* ─────────────── reduced motion ─────────────── */
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .reveal { opacity: 1; transform: none; transition: none; }
  .marquee__track { animation: none; }
  .hero__arrow { animation: none; }
  .gate { display: none; }
  .portal { height: auto; }
  .portal__sticky { position: relative; height: auto; padding: 4rem 0; }
  .portal__frame { --pw: 92vw; --ph: 80svh; --pr: 24px; --pcap: 1; margin: 0 auto; }
  .portal__hint { display: none; }
  .cursor { display: none; }
}

