dev-browser --headless <<'EOF'
const page = await browser.getPage("elysian");
await page.reload({ waitUntil: "networkidle" });
await page.waitForTimeout(2400);
const row = page.locator(".artifact__row").nth(2);
await row.scrollIntoViewIfNeeded();
await page.waitForTimeout(500);
const box = await row.boundingBox();
await page.mouse.move(box.x + box.width/2, box.y + box.height/2, { steps: 10 });
await page.waitForTimeout(1200);
await saveScreenshot(await page.screenshot(), "e4-lens.png");
console.log("ok");
EOF

dev-browser --headless <<'EOF'
const page = await browser.getPage("elysian");
await page.mouse.move(20, 20);
await page.locator("#scholars").scrollIntoViewIfNeeded();
await page.waitForTimeout(1300);
await saveScreenshot(await page.screenshot(), "e5-scholars.png");
// portal stages: scroll to 30%, 65%, 95% of the portal section
const stages = await page.evaluate(() => {
  const p = document.getElementById("valley");
  const top = p.getBoundingClientRect().top + scrollY;
  const total = p.offsetHeight - innerHeight;
  return [top + total*0.25, top + total*0.6, top + total*0.97];
});
for (let i = 0; i < 3; i++) {
  await page.evaluate((y) => scrollTo(0, y), stages[i]);
  await page.waitForTimeout(700);
  await saveScreenshot(await page.screenshot(), `e6-portal-${i}.png`);
}
console.log("ok");
EOF

dev-browser --headless <<'EOF'
const page = await browser.getPage("elysian");
await page.locator("#temple").scrollIntoViewIfNeeded();
await page.evaluate(() => scrollBy(0, innerHeight * 0.55));
await page.waitForTimeout(1500);
await saveScreenshot(await page.screenshot(), "e7-temple.png");
await page.locator("#audienceBtn").click();
await page.waitForTimeout(700);
await page.evaluate(() => scrollTo(0, document.body.scrollHeight));
await page.waitForTimeout(900);
await saveScreenshot(await page.screenshot(), "e8-footer.png");
console.log("ok");
EOF

