const page = await browser.getPage("mobile");
await page.setViewportSize({ width: 390, height: 844 });
const errors = [];
page.on("pageerror", e => errors.push(String(e)));
await page.goto("http://127.0.0.1:4173/", { waitUntil: "networkidle" });
await page.waitForTimeout(2600);
await saveScreenshot(await page.screenshot(), "m1-hero.png");
await page.locator("#collection").scrollIntoViewIfNeeded();
await page.waitForTimeout(800);
await saveScreenshot(await page.screenshot(), "m2-collection.png");
await page.locator("#scholars").scrollIntoViewIfNeeded();
await page.waitForTimeout(900);
await saveScreenshot(await page.screenshot(), "m3-scholars.png");
const stages = await page.evaluate(() => {
  const p = document.getElementById("valley");
  const top = p.getBoundingClientRect().top + scrollY;
  return top + (p.offsetHeight - innerHeight) * 0.97;
});
await page.evaluate((y) => scrollTo(0, y), stages);
await page.waitForTimeout(800);
await saveScreenshot(await page.screenshot(), "m4-portal.png");
await page.evaluate(() => scrollTo(0, document.body.scrollHeight - innerHeight*1.15));
await page.waitForTimeout(1200);
await saveScreenshot(await page.screenshot(), "m5-temple.png");
console.log(JSON.stringify({ errors }));
EOF

